  "uk-domestic.json": "{\n  \"header\": {\n    \"scheme\": \"uk\",\n    \"part\": \"domestic\",\n    \"authority\": \"HM Revenue and Customs, United Kingdom\",\n    \"instrument\": \"Benchmark scale rates for subsistence, Income Tax (Earnings and Pensions) Act 2003 s.289A, published at EIM05231\",\n    \"source_url\": \"https://www.gov.uk/hmrc-internal-manuals/employment-income-manual/eim05231\",\n    \"effective_date\": \"2019-04-06\",\n    \"retrieved_date\": \"2026-09-05\",\n    \"currency\": \"GBP\",\n    \"note\": \"The benchmark rates are the maximum that may be paid free of tax without receipts. They are payable only for a meal the traveller actually buys while on a qualifying journey, and only when a checking system is in place. They are not a lodging allowance.\"\n  },\n  \"rates\": [\n    {\n      \"country\": \"United Kingdom\",\n      \"code\": \"GB\",\n      \"currency\": \"GBP\",\n      \"bands\": [\n        { \"min_hours\": 5, \"amount_minor\": 500, \"meals_covered\": 1, \"label\": \"5 hours or more (one meal rate)\" },\n        { \"min_hours\": 10, \"amount_minor\": 1000, \"meals_covered\": 2, \"label\": \"10 hours or more (two meal rate)\" },\n        { \"min_hours\": 15, \"amount_minor\": 2500, \"meals_covered\": 3, \"label\": \"15 hours or more and ongoing at 8pm\" }\n      ],\n      \"late_evening_supplement_minor\": 1000,\n      \"note\": \"A supplementary late-evening rate of 10.00 GBP may be paid on top of the 5-hour or 10-hour rate when the journey is ongoing at 8pm and the traveller had to buy a meal after that time. This server does not add it automatically: whether a meal was bought after 8pm is a fact the caller has to supply, so it is exposed as late_evening on perdiem_calc.\"\n    }\n  ]\n}\n",
  "uk-overseas.json": "{\n  \"header\": {\n    \"scheme\": \"uk\",\n    \"part\": \"overseas\",\n    \"authority\": \"HM Revenue and Customs, United Kingdom\",\n    \"instrument\": \"Worldwide subsistence rates (overseas scale rates) for employees travelling outside the UK, EIM05250 and the accompanying country and city table\",\n    \"source_url\": \"https://www.gov.uk/guidance/expenses-rates-for-employees-travelling-outside-the-uk\",\n    \"effective_date\": \"unknown\",\n    \"retrieved_date\": \"2026-09-05\",\n    \"currency\": \"per city\",\n    \"bundled\": false,\n    \"coverage\": \"NOT BUNDLED. The HMRC overseas table gives, per city, a room rate plus separate breakfast, lunch, dinner, other and drinks figures and a 24-hour and over-5-hour and over-10-hour total, all in the destination currency. Those are roughly 250 cities times 8 figures. This build could not state them with confidence from public regulation text alone, so under the project rule none of them is bundled: an invented per-city figure would be a tax-relief number that is wrong and looks authoritative. Use scheme \\\"uk\\\" for the domestic benchmark scale rates, and for an overseas UK claim read the live table at the source URL.\",\n    \"note\": \"The file is kept, with an empty rates array, so the scheme shape is stable and a later build can fill it in without a schema change. perdiem_rates {scheme:\\\"uk\\\", part:\\\"overseas\\\"} says this in the answer rather than returning an empty list with no explanation.\"\n  },\n  \"rates\": []\n}\n",
